  async function mineNearbyLapis() {
    for (let i = 0; i < 8; i++) {
      if (countItem("lapis_lazuli") >= 8) return true;
      const lapis = bot.findBlock({
        matching: block => block.name === "lapis_ore" || block.name === "deepslate_lapis_ore",
        maxDistance: 32
