async function craftIronSwordFromAvailableRawIron(bot) {
  if (countItem(bot, "iron_sword") >= 1) return;
  if (countItem(bot, "stick") < 1) {
    if (countItem(bot, "jungle_planks") >= 2) {
      await craftItem(bot, "stick", 1);
