    maxDistance: 32
  });
  if ((craftingTable || countItem(bot, "crafting_table") > 0) && countItem(bot, "cobblestone") >= 3 && countItem(bot, "stick") >= 2) {
    await craftItem(bot, "stone_pickaxe", 1);
