          goalType: "wood",
          quantity: 1,
          maxSearchBudgetSec: 24
        });
        if (!result.success) throw new Error(result.reason || "WOOD_SEARCH_FAILED");
        if (countItem(bot, "oak_log") > 0) {
          await craftItem(bot, "oak_planks", 1);
        } else if (countItem(bot, "birch_log") > 0) {
